-- =============================================================================
-- Eden Apothecary: pre-1900 energetics sources for 50 herbs (research batches 1
-- and 2). DATA + one new read-only view. Written 2026-09-15, NOT applied.
-- =============================================================================
-- Founder decisions, 2026-09-15 (memory p_herb_evidence_honesty_2026_09_15):
--   * Every pre-1900 source found for a herb's temperature/moisture is SHOWN on
--     the herb page, with its citation. Where the sources disagree the page says
--     so plainly. A disagreement is never hidden.
--   * The value the app matches on is the modern reading of what the herb DOES
--     in the body. Old sources corroborate, add, or break ties only; the
--     majority-of-first-hand rule applies ONLY where the modern value is unclear
--     or missing (July 2026 ruling wins), with the oldest first-hand source
--     breaking a tie.
--   * A herb with no qualifying source is marked 'no pre-1900 source found',
--     never guessed.
--   * Sources are a Root feature (herb tier model, 20260916100000). The
--     disagreement sentence and the no-source line are FREE, because honesty
--     about the evidence is not a paid feature.
--
-- WHAT THIS MIGRATION DOES
--   1. Writes public.herbs.energetics_citation for 50 herbs that had NULL
--      (12 with sources that agree, 16 where they disagree, 19 with no pre-1900
--      source found). Backward compatible: the column stays a jsonb OBJECT. The
--      69 herbs that already carry the older single-source object are NOT touched
--      and keep their shape; the new object adds a 'sources' ARRAY plus 'rule',
--      'sources_agree', 'agreement_state', 'disagreement_text',
--      'checked_no_reading' and 'batch'. A row is identified as a batch object by
--      the 'batch' key, which the old shape never had.
--   2. Applies exactly THREE app-value changes, each founder-approved and each
--      replacing an UNCLEAR stored value on a single named pre-1900 source:
--        H132 Sarsaparilla: temperature 'Neutral (gently warming as a hot decoction; sources range cool to warm)'
--            -> 'Warm'
--        H120 Spikenard (Nard, Jatamansi): moisture 'Neutral (grounding and faintly unctuous; not drying)'
--            -> 'Dry'
--        H287 Bogbean (Buckbean): temperature 'Cold'
--            -> 'Warm'
--      No other temperature or moisture changes. Every UPDATE is guarded on the
--      exact value read live on 2026-09-15 and RAISEs if the guard fails; a
--      re-run where the value is already corrected is a no-op with a notice.
--   3. Creates public.herb_energetics_evidence_v, a read-only view that carries
--      the evidence to the herb page. Free and anon get the plain-English fields
--      (agreement state, the disagreement sentence, the no-source flag, the basis
--      line, a source count). The sources themselves, the texts searched that gave
--      no reading, and the vote tally are NULL below Root.
--
-- BLAST RADIUS: production data on 50 of 300 herbs in public.herbs, plus one new
-- client-readable view. No column is dropped, no existing view is replaced, no
-- RLS policy changes. The three value changes move what the pattern matcher
-- computes for those three herbs. Read-only for every other herb.
--
-- IDEMPOTENT. Verification DO blocks at the bottom abort the whole transaction
-- if any assertion fails, including a snapshot check that NO herb other than the
-- three named above changed temperature or moisture.
-- =============================================================================

begin;

-- -----------------------------------------------------------------------------
-- 0. Snapshot: every herb's energetics, as they stand before this migration.
--    Section 4 asserts that exactly the three approved rows moved.
-- -----------------------------------------------------------------------------
create temporary table _energetics_before on commit drop as
  select herb_id, temperature, moisture from public.herbs;

-- -----------------------------------------------------------------------------
-- 1. The three founder-approved app-value changes.
-- -----------------------------------------------------------------------------

-- H132 Sarsaparilla: temperature, stored value was unclear; set from the named pre-1900 source.
do $do$
declare n int;
begin
  update public.herbs
     set temperature = 'Warm',
         last_updated = now()
   where herb_id = 'H132'
     and temperature = 'Neutral (gently warming as a hot decoction; sources range cool to warm)';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs
                where herb_id = 'H132' and temperature = 'Warm') then
      raise notice 'H132.temperature already corrected, skipped';
    else
      raise exception 'H132.temperature: live value no longer matches the value read 2026-09-15; not updated';
    end if;
  end if;
end
$do$;

-- H120 Spikenard (Nard, Jatamansi): moisture, stored value was unclear; set from the named pre-1900 source.
do $do$
declare n int;
begin
  update public.herbs
     set moisture = 'Dry',
         last_updated = now()
   where herb_id = 'H120'
     and moisture = 'Neutral (grounding and faintly unctuous; not drying)';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs
                where herb_id = 'H120' and moisture = 'Dry') then
      raise notice 'H120.moisture already corrected, skipped';
    else
      raise exception 'H120.moisture: live value no longer matches the value read 2026-09-15; not updated';
    end if;
  end if;
end
$do$;

-- H287 Bogbean (Buckbean): temperature, stored value was unclear; set from the named pre-1900 source.
do $do$
declare n int;
begin
  update public.herbs
     set temperature = 'Warm',
         last_updated = now()
   where herb_id = 'H287'
     and temperature = 'Cold';
  get diagnostics n = row_count;
  if n <> 1 then
    if exists (select 1 from public.herbs
                where herb_id = 'H287' and temperature = 'Warm') then
      raise notice 'H287.temperature already corrected, skipped';
    else
      raise exception 'H287.temperature: live value no longer matches the value read 2026-09-15; not updated';
    end if;
  end if;
end
$do$;

-- -----------------------------------------------------------------------------
-- 2. The researched sources, one INSERT per herb into a staging table, applied
--    under a single guard loop. The guard refuses to overwrite anything that is
--    not NULL and not already a batch object.
-- -----------------------------------------------------------------------------
create temporary table _energetics_batch (
  herb_id text primary key,
  citation jsonb not null
) on commit drop;

-- H102 Hibiscus (batch 1, 0 sources, no qualifying source)
insert into _energetics_batch values ('H102', $j${"agreement_state": "none", "app_value": {"moisture": "Moist", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 1, "checked_no_reading": ["Dymock, Pharmacographia Indica Vol. I (1890), 'Hibiscus Subdariffa': diet and jelly uses, 'emollient and demulcent properties', no temperature or moisture", "Watt, Dictionary of the Economic Products of India Vol. IV (1890), Hibiscus Sabdariffa: no thermal quality", "Ainslie, Materia Indica Vol. II (1826) p. 335: root purgative (after Dancer), no thermal quality", "King's American Dispensatory 1898: no entry assigning a thermal quality"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_pre1900_source_found": true, "notes": [], "part_used": "Calyx (dried)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

-- H104 Rehmannia (batch 1, 6 sources, sources agree)
insert into _energetics_batch values ('H104', $j${"agreement_state": "agree", "app_value": {"moisture": "Moist", "temperature": "Warm (prepared); Cold (raw)"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources agree)", "temperature": "stays Warm prepared and Cold raw (clear modern value for each form; old sources agree)"}, "batch": 1, "checked_no_reading": [], "counted_readings": {"moisture": [{"reading": "Moist", "source": "Bencao Congxin (1757)"}], "temperature": [{"reading": "Warm (prepared)", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm (prepared)", "source": "Bencao Congxin (1757)"}, {"reading": "Cool (raw)", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Cool (raw)", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "", "no_pre1900_source_found": false, "notes": ["Stored value splits prepared (Warm) and raw (Cold); the rule was applied to each form separately."], "part_used": "Root (prepared, Shu Di Huang; the raw form is Sheng Di Huang)", "researched": "2026-09-15", "rule": "Temperature: stored value clear for each form, so it stays. Prepared root: Bencao Gangmu and Bencao Congxin both warm. Raw root: Shennong Bencao Jing and Bencao Congxin both cold (the Bencao Gangmu heading copies Shennong). Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: shown on temperature as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "熟地黄 … 氣味甘微苦微温無毒", "gloss": "Prepared rehmannia: taste sweet, slightly bitter; nature slightly warm; not toxic.", "locator": "卷十六 草之五, 地黄, 熟地黄 subsection; https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/卷16", "not_counted_why": "", "note": "Prepared root, the form stored as primary.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: shown on temperature as the source words it, which the app value does not reduce to one direction.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "熟地黃 … 甘而微溫", "gloss": "Prepared rehmannia: sweet and slightly warm.", "locator": "卷三 草部, 熟地黃", "not_counted_why": "", "note": "Prepared root.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. Raw dried root, not the prepared form. Counted for the raw form only; agrees with stored raw value.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "干地黃　味甘，寒。", "gloss": "Dried rehmannia: sweet, cold.", "locator": "上經, 干地黃", "not_counted_why": "Raw dried root, not the prepared form. Counted for the raw form only; agrees with stored raw value.", "note": "Raw dried root, not the prepared form. Counted for the raw form only; agrees with stored raw value.", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. Raw form only. The heading repeats the Shennong reading for dried rehmannia, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "乾地黄 … 氣味甘寒無毒 … 生地黄氣味大寒", "gloss": "Dried rehmannia sweet and cold; fresh rehmannia very cold.", "locator": "卷十六, 地黄 main heading and 生地黄 subsection", "not_counted_why": "Raw form only. The heading repeats the Shennong reading for dried rehmannia, so it counts once, credited to Shennong.", "note": "Raw form only. The heading repeats the Shennong reading for dried rehmannia, so it counts once, credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Cold", "corpus": "chinese", "counted": true, "counted_moisture": true, "counted_temperature": false, "excerpt": "乾地黃 … 苦甘而寒 … 性寒而潤", "gloss": "Dried rehmannia: bitter, sweet and cold; its nature is cold and moistening.", "locator": "卷三 草部, 乾地黃", "not_counted_why": "", "note": "Raw form. '性寒而潤' (its nature is cold and moistening) is a nature statement; under the final rules 潤 counts as Moist. Temperature counted for the raw form only.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. Not a thermal slot under the strict felt-heat rule ('cooling' describes use).", "assigns_moisture": null, "assigns_temperature": null, "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "The root is largely prescribed as a cooling and purifying drug", "gloss": "Action description.", "locator": "s.v. REHMANNIA CHINENSIS", "not_counted_why": "Not a thermal slot under the strict felt-heat rule ('cooling' describes use).", "note": "Not a thermal slot under the strict felt-heat rule ('cooling' describes use).", "short": "Porter Smith (1871)", "source": "F. Porter Smith, Contributions towards the Materia Medica & Natural History of China", "tier": "first-hand", "tradition": "Chinese", "url": "https://archive.org/download/b24876288/b24876288_djvu.txt", "year": "1871"}], "sources_agree": true, "stored_before": {"moisture": "Moist", "temperature": "Warm (prepared, Shu Di Huang); Cold (raw, Sheng Di Huang)"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "definite values for each form: Warm prepared, Cold raw"}}}$j$::jsonb);

