insert into _energetics_batch values ('H120', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": true, "temperature": false}, "app_value_lines": {"moisture": "Neutral to Dry (stored value unclear; majority of first-hand sources; only one gives a reading: Culpeper (1653) dry)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 1, "checked_no_reading": ["Dutt 1877, Nardostachys Jatamansi: 'nervine tonic', no thermal quality", "Leclerc, Ibn al-Baytar Vol. II (1881) no. 1237 Sonbol: no degree given for Indian nard in the text as scanned"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Cool", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Cool", "source": "Rajanighantu (c. 15th c.)"}, {"reading": "Warm", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}, {"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "On temperature, the old sources disagree: Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as cool; Bencao Gangmu (1596), Bencao Congxin (1757) and Culpeper (1653) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "Rhizome and root (dried, aromatic)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool with a classical basis (sheeta virya)), so it stays Cool. Moisture: stored value unclear (the record says Neutral was chosen so the moisture stays consistent with the cool temperature and asks for confirmation, and the stored field hedges ('faintly unctuous')); majority of first-hand sources; only one gives a reading: Culpeper (1653) dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; 