ed_moisture": false, "counted_temperature": false, "excerpt": "The Hindus use the fruit and root; they regard them as having Cooling, diuretic, tonic and aphrodisiac properties", "gloss": "Reports Hindu use; 'cooling' in a list of actions.", "locator": "Vol. I p. 243, TRIBULUS TERRESTRIS", "not_counted_why": "Second-hand, and an action list.", "note": "Second-hand, and an action list.", "short": "Pharmacographia Indica I (1890)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. I", "tier": "second-hand-report", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0001/b21960343_0001_djvu.txt", "year": "1890"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Cool (Ayurvedic sheeta virya; the Chinese tradition classes the fruit as slightly Warm, but the cooling Ayurvedic potency is used as the anchor here)."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Cool anchored in the record to the Ayurvedic sheeta virya"}}}$j$::jsonb);

