-- H179 Guduchi (Giloy) (batch 1, 3 sources, SOURCES DISAGREE)
insert into _energetics_batch values ('H179', $j${"agreement_state": "disagree", "app_value": {"moisture": "Neutral", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 1, "checked_no_reading": ["Dutt 1877, Tinospora cordifolia: uses only", "Ainslie 1826 Vol. II, Menispermum cordifolium: none"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "On temperature, Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "Stem (the mature climbing stem is the officinal part; the root is used secondarily, and a purified aqueous starch extract of the stem, guduchi satva, is a traditional form)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite 'Cool (functional)', the July 2026 ruling's own example of a clear modern value), so it stays Cool. Moisture: stored value clear (a definite Neutral, argued in the record), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "गुडूची कटुका तिक्ता स्वादुपाका रसायनी । संग्राहिणी कषायोष्णा लघ्वी बल्याऽग्निदीपिनी ॥", "gloss": "guḍūcī kaṭukā tiktā svādupākā rasāyanī, saṃgrāhiṇī kaṣāyoṣṇā laghvī: guduchi is pungent, bitter, sweet after digestion, rejuvenative, binding, astringent and HOT, light, strengthening, kindles digestion.", "locator": "Guḍūcyādi varga 4.8-9", "not_counted_why": "", "note": "", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "jñeyā guḍūcī gurur uṣṇavīryā tiktā kaṣāyā jvaranāśinī ca", "gloss": "Guduchi is heavy, of HOT potency, bitter, astringent, destroys fever.", "locator": "Rājanighaṇṭu 3.17", "not_counted_why": "", "note": "", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": "Dry", "assigns_temperature": "Cool / Warm", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "It is considered to be cold and dry, or according to Arabic and Persian writers, hot and dry in the first degree.", "gloss": "Reports two opposite views: (Hindu) cold and dry; (Arabic/Persian) hot and dry, first degree.", "locator": "Vol. I pp. 54-55, TINOSPORA CORDIFOLIA, History, Uses &c.", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Pharmacographia Indica I (1890)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. I", "tier": "second-hand-report", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0001/b21960343_0001_djvu.txt", "year": "1890"}], "sources_agree": false, "stored_before": {"moisture": "Neutral. A bitter alterative with a drying, toxin-clearing tendency that is offset by its unctuous (snigdha) rasayana quality and sweet post-digestive effect, keeping it broadly Vata-neutral and usable in convalescence and depletion, so on balance it is neither markedly drying nor moistening.", "temperature": "Cool (functional). Classical Ayurveda assigns Guduchi a hot potency (ushna virya), yet its signature clinical role is antipyretic and Pitta-pacifying and it is the premier remedy for fevers, inflammation, and heat, so in the Western energetic column encoded here it reads as cooling in effect. The classical ushna virya is noted and flagged for the reviewer."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral, argued in the record"}, "temperature": {"status": "clear", "why": "a definite 'Cool (functional)', the July 2026 ruling's own example of a clear modern value"}}}$j$::jsonb);

-- H180 Japanese Honeysuckle (Jin Yin Hua) (batch 1, 4 sources, SOURCES DISAGREE)
insert into _energetics_batch values ('H180', $j${"agreement_state": "disagree", "app_value": {"moisture": "Neutral", "temperature": "Cold"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (clear modern value; no pre-1900 source found)", "temperature": "stays Cold (clear modern value; old sources disagree, shown on page)"}, "batch": 1, "checked_no_reading": ["Porter Smith 1871, Lonicera: actions only"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Warm", "source": "Bencao Gangmu (1596)"}, {"reading": "Neutral", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "On temperature, the old sources disagree: Bencao Gangmu (1596) reads it as warm; Bencao Congxin (1757) reads it as neutral. The app keeps cold, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "Flower bud (the dried flower bud and partially opened flower, Lonicerae Japonicae Flos)", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cold), so it stays Cold. Moisture: stored value clear (a definite Neutral), so it stays Neutral.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "忍冬 {别錄上品} … 氣味甘温無毒 {權曰辛 藏器曰小寒云温者非也}", "gloss": "Honeysuckle: sweet, warm (Zhen Quan: pungent; Chen Cangqi: slightly cold, 'those who say warm are wrong').", "locator": "卷十八下 草之七, 忍冬 (釋名 金銀藤)", "not_counted_why": "", "note": "The entry covers vine, leaf and flower together. The heading most likely reproduces the Mingyi Bielu (c. 500 CE), which could not be opened as a separate text; it counts once either way.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: differs from the app temperature (source neutral, app cool).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "金銀花 … 甘平。除熱解毒。… 性极中和。", "gloss": "Honeysuckle flower: sweet, NEUTRAL; its nature is extremely balanced.", "locator": "卷五 草部, 金銀花", "not_counted_why": "", "note": "", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": null, "assigns_temperature": "Cool", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "藏器曰小寒云温者非也", "gloss": "Chen Cangqi (8th c.): slightly cold; warm is wrong.", "locator": "卷十八下, 忍冬 氣味 note", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "second-hand-report", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Species problem: Lonicera periclymenum, not L. japonica. Not counted.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Honeysuckle is neither cold nor binding; but hot, and attenuating or making thin.", "gloss": "European woodbine is hot.", "locator": "Book II, Chap. 329 'Of Woodbine, or Honeysuckle', The Temperature", "not_counted_why": "Species problem: Lonicera periclymenum, not L. japonica. Not counted.", "note": "Species problem: Lonicera periclymenum, not L. japonica. Not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Neutral", "temperature": "Cold"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Neutral"}, "temperature": {"status": "clear", "why": "a definite Cold"}}}$j$::jsonb);

-- H183 Pinellia (Ban Xia) (batch 1, 5 sources, SOURCES DISAGREE)
insert into _energetics_batch values ('H183', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 1, "checked_no_reading": ["Porter Smith 1871, Midsummer Root (Pwan-hia): preparation and identity only"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Bencao Congxin (1757)"}], "temperature": [{"reading": "Neutral", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Congxin (1757)"}, {"reading": "Warm", "source": "Bencao Gangmu (1596)"}]}, "disagreement_text": "On temperature, the old sources disagree: Shennong Bencao Jing (c. 200 CE) reads it as neutral; Bencao Congxin (1757) and Bencao Gangmu (1596) read it as warm. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it. Li Shizhen, in Bencao Gangmu, also says it is a mistake to call pinellia drying in nature; Bencao Congxin calls it drying and then quotes that same objection.", "no_pre1900_source_found": false, "notes": [], "part_used": "Rhizome (the dried tuber), processed only. Standard detoxified forms are Jiang Ban Xia (ginger-and-alum processed), Fa Ban Xia (licorice-and-lime processed), and Qing Ban Xia (alum processed). The raw, unprocessed tuber (Sheng Ban Xia) is toxic and is not for internal use except by expert prescription.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm per later standard materia medica), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source neutral, app warm).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "半夏　味辛，平。", "gloss": "Pinellia: pungent, neutral.", "locator": "下經, 半夏", "not_counted_why": "", "note": "", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. The heading repeats the Shennong reading (辛平) word for word, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "根氣味辛平有毒 {别録曰生微寒熟温 … 元素曰味辛苦性温}", "gloss": "Root: pungent, neutral, toxic (Bielu: raw slightly cold, processed warm; Zhang Yuansu: nature warm).", "locator": "卷十七下 草之六, 半夏", "not_counted_why": "The heading repeats the Shennong reading (辛平) word for word, so it counts once, credited to Shennong.", "note": "The heading repeats the Shennong reading (辛平) word for word, so it counts once, credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "半夏 … 辛溫。体滑性燥。", "gloss": "Pinellia: pungent, warm; body slippery, nature drying.", "locator": "卷四 草部, 半夏", "not_counted_why": "", "note": "'性燥' (drying nature) counts as Dry under the final rules. The same entry then quotes, in its own commentary, Li Shizhen's view that calling pinellia drying is a mistake, so this source contradicts itself.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Shown for context. Speaks directly to the processed form, which is the stored part.", "assigns_moisture": null, "assigns_temperature": "Warm (processed)", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "别録曰生微寒熟温", "gloss": "Bielu: raw slightly cold, processed (cooked) warm.", "locator": "卷十七下, 半夏 氣味 note", "not_counted_why": "Speaks directly to the processed form, which is the stored part.", "note": "Speaks directly to the processed form, which is the stored part.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "second-hand-report", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "時珍曰…半夏能主痰飲及腹脹者為其體滑而味辛性温也涎滑能潤…世俗皆以南星半夏為性燥誤矣濕去則土燥痰涎不生非二物之性燥也", "gloss": "Li Shizhen's own view: pinellia is slippery in body, pungent and WARM in nature; its slipperiness can moisten; the common belief that it is drying in nature is a mistake.", "locator": "卷十七下 草之六, 半夏, 發明 (時珍曰)", "not_counted_why": "", "note": "Li Shizhen's own statement (性温, warm nature), which departs from the Shennong reading he reproduced in the heading; counted as Bencao Gangmu's own reading, as with his own notes on goji and madder. His denial of the drying label is a denial, not a moisture reading, so it is shown as context for moisture.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm per later standard materia medica"}}}$j$::jsonb);

-- H189 Bibhitaki (Baheda / Belleric Myrobalan) (batch 1, 5 sources, sources agree)
insert into _energetics_batch values ('H189', $j${"agreement_state": "agree", "app_value": {"moisture": "Dry", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Warm (clear modern value; old sources agree)"}, "batch": 1, "checked_no_reading": ["Dutt 1877, Terminalia Bellerica: 'astringent and laxative', kernel 'narcotic', no thermal quality", "Dymock Vol. II (1891), Terminalia belerica: action words only"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Bhavaprakasha (16th c.)"}], "temperature": [{"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Dried ripe fruit rind (pericarp of the fruit); the medicinal part is the fleshy rind, not the seed kernel", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm per the Ayurvedic ushna virya), so it stays Warm. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (warm); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "विभीतकं स्वादुपाकं कषायं कफपित्तनुत् । उष्णवीर्यं हिमस्पर्शं भेदनं कासनाशनम् ॥ रूक्षं नेत्रहितं केश्यं …", "gloss": "vibhītakaṃ svādupākaṃ kaṣāyaṃ … uṣṇavīryaṃ himasparśaṃ … rūkṣaṃ: belleric myrobalan is sweet after digestion, astringent, removes phlegm and bile, of HOT potency though cold to the touch, laxative, stops cough; DRY, good for the eyes and hair.", "locator": "Harītakyādi varga 2.36-37", "not_counted_why": "", "note": "The text itself separates potency (hot) from touch (cold).", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: agrees with the app temperature (warm).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "vibhītakaḥ kaṭus tiktaḥ kaṣāyoṣṇaḥ kaphāpahaḥ", "gloss": "Belleric myrobalan is pungent, bitter, astringent and HOT, removes phlegm.", "locator": "Rājanighaṇṭu 11.232", "not_counted_why": "", "note": "", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "All the kinds of Mirobalans are in taste astringent and sharp … and therefore they are of complexion cold and dry.", "gloss": "All myrobalans, belleric named among them, are cold and dry.", "locator": "Book III, Chap. 128 'Of the Indian Plum, or Mirobalans', The Temperature; scan p. 1501.", "not_counted_why": "Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "note": "Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/herballorgeneral00gera/herballorgeneral00gera_djvu.txt", "year": "1633"}, {"agreement": "Shown for context. Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "All the sorts or Myrobalans, purge the stomach … they are cold and dry", "gloss": "All myrobalans ('Bellericks' among them in Culpeper's list) are cold and dry.", "locator": "Catalogue of simples, Fruits (Gutenberg #49513 lines ~17638 and ~19036)", "not_counted_why": "Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "note": "Group statement (covers a whole group of plants, not this species by name). Shown as context, not counted.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "unani", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Ishak ibn Amrân … Il est froid et astringent. … Avicenne. Il est froid au premier degré et sec au second.", "gloss": "Ibn al-Baytar quotes Ishaq ibn Imran: cold and astringent; and Avicenna: cold in the first degree, dry in the second.", "locator": "Vol. I, no. 338 'Beliledj, Belliric', pp. 258-259", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Ibn al-Baytar, tr. Leclerc (1877)", "source": "Ibn al-Baytar, Traité des simples, tr. Lucien Leclerc, Vol. I (Notices et extraits des manuscrits, t. 23, pt. 1)", "tier": "second-hand-report", "tradition": "Unani (Arabic)", "url": "https://archive.org/download/NoticesEtExtraitsDesMss23P1/Notices_et_extraits_des_mss_23_p1_djvu.txt", "year": "1877"}], "sources_agree": true, "stored_before": {"moisture": "Dry", "temperature": "Warm (Ayurvedic virya: ushna). The tannic astringency reads as cooling to the touch, yet the operative potency is warming and drying, which is why it reduces cold, damp kapha."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm per the Ayurvedic ushna virya"}}}$j$::jsonb);

-- H190 Cranberry (American Cranberry, Large Cranberry) (batch 1, 1 source, single reading)
insert into _energetics_batch values ('H190', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 1, "checked_no_reading": ["King's 1898, Vaccinium: none"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_pre1900_source_found": false, "notes": [], "part_used": "Ripe fruit (berry) and its expressed juice; concentrated whole-fruit and standardized proanthocyanidin (PAC) extracts of the fruit are the common modern medicinal forms.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool, argued in the record), so it stays Cool. Moisture: stored value clear (a definite Dry, argued in the record), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Shown for context. Species problem: this is the European small cranberry (Vaccinium oxycoccos), not the American V. macrocarpon. Not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "These Whortleberries are cold and dry, having withal a certain thinness of parts", "gloss": "Marsh whortleberries (fen-berries) are cold and dry.", "locator": "Book III, Chap. 74 'Of the Marsh Whortleberries or Fen-Berries', The Temperature", "not_counted_why": "Species problem: this is the European small cranberry (Vaccinium oxycoccos), not the American V. macrocarpon. Not counted.", "note": "Species problem: this is the European small cranberry (Vaccinium oxycoccos), not the American V. macrocarpon. Not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}], "sources_agree": false, "stored_before": {"moisture": "Dry. Although it is usually taken as juice, and so delivers fluid, the fruit's astringent tannins and proanthocyanidins are drying and tightening to the tissues, so its operative moisture is dry.", "temperature": "Cool. The sour taste is classically read as warming, yet the operative energetic of the ripe fruit and its astringent tannins is cooling and drying, which is why it suits hot, damp, inflamed urinary conditions. Several Western traditions read the raw, sour berry as cold."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry, argued in the record"}, "temperature": {"status": "clear", "why": "a definite Cool, argued in the record"}}}$j$::jsonb);

-- H193 Vasa (Malabar Nut, Vasaka) (batch 1, 2 sources, sources agree)
