insert into _energetics_batch values ('H200', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 2, "checked_no_reading": ["Salmon, Botanologia (1710), 'Of Kneeholm': Qualities are action words only (aperitive, diuretic, vulnerary), no temperature", "Culpeper's herbal chapter 'Butcher's Broom': 'a plant of Mars', no degree"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}]}, "disagreement_text": "On temperature, Gerard (1633) and Culpeper (1653) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "Rhizome and root (the dried rootstock, Rhizoma Rusci). The aerial cladodes and berries were used in older folk practice, but the modern venotonic drug is the rhizome and root.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool, explained in the record as the dominant modern venotonic and anti-inflammatory reading), so it stays Cool. Moisture: stored value clear (a definite Dry, explained from the astringent and diuretic action), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The roots of Knee-Holm, which be chiefly used, are of temperature hot, and meanly dry, with a thinness of essence.", "gloss": "The roots are hot and moderately dry.", "locator": "Book II, Chap. 338 'Of Knee-Holm, or Butcher's Broom', The Temperature", "not_counted_why": "", "note": "", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Rusci. Of Knee-holly or Butchers-broom, or Bruscus. They are meanly hot and dry, provoke urine, break the stone", "gloss": "The roots are moderately hot and dry. His root tables also list Knee-holly as hot in the first degree and dry in the first degree.", "locator": "Catalogue of simples, Roots, 'Rusci' (Gutenberg #49513 line ~15818); root degree tables (lines ~18257 and ~18288)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}], "sources_agree": false, "stored_before": {"moisture": "Dry. The astringency tightens and dries slack, weeping tissue, and the diuretic action drains fluid, so the herb is drying overall.", "temperature": "Cool. The root is astringent and anti-inflammatory, cooling the heat of engorged, inflamed veins and hemorrhoids. Grieve's older Eclectic reading counted it a diaphoretic and diuretic, which some traditions read as gently warming; the dominant modern venotonic and anti-inflammatory picture places it on the cool side."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry, explained from the astringent and diuretic action"}, "temperature": {"status": "clear", "why": "a definite Cool, explained in the record as the dominant modern venotonic and anti-inflammatory reading"}}}$j$::jsonb);

