insert into _energetics_batch values ('H206', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 2, "checked_no_reading": ["Dutt, Materia Medica of the Hindus 1877, Rubia cordifolia: 'regarded as astringent', no thermal quality", "Porter Smith 1871, RUBIA MUNJISTA: 'tonic, alterative, astringent, vulnerary and emmenagogue properties are ascribed', actions only"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Cool", "source": "Shennong Bencao Jing (c. 200 CE)"}, {"reading": "Warm", "source": "Bencao Gangmu (1596)"}, {"reading": "Warm", "source": "Bhavaprakasha (16th c.)"}, {"reading": "Warm", "source": "Rajanighantu (c. 15th c.)"}]}, "disagreement_text": "On temperature, the old sources disagree: Shennong Bencao Jing (c. 200 CE) reads it as cold; Bencao Gangmu (1596), Bhavaprakasha (16th c.) and Rajanighantu (c. 15th c.) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": ["The record treats the hot Ayurvedic reading as a minority view; both Sanskrit texts opened here, the Bhavaprakasha and the Rajanighantu, give hot (uṣṇa). Worth checking against the record's own Ayurvedic source."], "part_used": "Root and rhizome (the red-orange roots; the classical Ayurvedic and Chinese medicinal drug, Radix et Rhizoma Rubiae / Qian Cao Gen). The Ayurvedic Pharmacopoeia of India also carries a monograph for the dried stem, but the root is the dominant traditional drug and is used here.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool; the record cites Ayurvedic sheeta virya and Chinese han), so it stays Cool. Moisture: stored value clear (a definite Dry, explained from the bitter and astringent tastes), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (cool).", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "茜根　味苦，寒。主寒濕，風痹，黃膽，補中。", "gloss": "Madder root: bitter, cold.", "locator": "上經, 茜根", "not_counted_why": "", "note": "", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. The heading repeats the Shennong reading word for word, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Cold", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "根…氣味苦寒無毒", "gloss": "Root: bitter, cold, not toxic.", "locator": "卷十八下 草之七, 茜草, 根 氣味", "not_counted_why": "The heading repeats the Shennong reading word for word, so it counts once, credited to Shennong.", "note": "The heading repeats the Shennong reading word for word, so it counts once, credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "時珍曰茜根色赤而氣温味微酸而帶鹹色赤入營氣温行滯", "gloss": "Li Shizhen's own judgement: the root is red and its nature is WARM, the taste slightly sour and salty; warm, so it moves stagnation.", "locator": "卷十八下 草之七, 茜草, 發明 (時珍曰)", "not_counted_why": "", "note": "Li Shizhen's own statement, which departs from the heading.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Copied almost word for word from Li Shizhen's note above, so it counts once, credited to Li Shizhen.", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "色赤入营。氣溫行滞。味酸走肝。而咸走血。（本經苦寒。）", "gloss": "Red, enters the nutritive level; nature warm, moves stagnation. (The Shennong says bitter, cold.)", "locator": "卷五 草部, 茜草", "not_counted_why": "Copied almost word for word from Li Shizhen's note above, so it counts once, credited to Li Shizhen.", "note": "Copied almost word for word from Li Shizhen's note above, so it counts once, credited to Li Shizhen.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "मञ्जिष्ठा मधुरा तिक्ता कषाया स्वरवर्णकृत् । गुरुरुष्णा विषश्लेष्मशोथयोन्यक्षिकर्णरुक् ॥", "gloss": "mañjiṣṭhā madhurā tiktā kaṣāyā svaravarṇakṛt, gurur uṣṇā: manjistha is sweet, bitter, astringent, good for the voice and complexion, heavy and HOT; removes poison, phlegm, swelling, and disorders of the womb, eye and ear.", "locator": "Harītakyādi varga 2.190-191", "not_counted_why": "", "note": "", "short": "Bhavaprakasha (16th c.)", "source": "Bhāvamiśra, Bhāvaprakāśa Nighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "https://sa.wikisource.org/wiki/भावप्रकाशः/पूर्वखण्डे_भावप्रकाशनिघण्टुः", "year": "16th century"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool).", "assigns_moisture": null, "assigns_temperature": "Warm", "corpus": "ayurvedic", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "mañjiṣṭhā madhurā svāde kaṣāyoṣṇā gurus tathā", "gloss": "Manjistha is sweet in taste, astringent and HOT, and heavy.", "locator": "Rājanighaṇṭu 5.194", "not_counted_why": "", "note": "", "short": "Rajanighantu (c. 15th c.)", "source": "Narahari, Rājanighaṇṭu (Sanskrit original)", "tier": "first-hand", "tradition": "Ayurvedic (Indian)", "url": "http://gretil.sub.uni-goettingen.de/gretil/corpustei/transformations/plaintext/sa_narahari-rAjanighaNTu.txt", "year": "c. 15th century"}, {"agreement": "Shown for context. Different species (Rubia tinctorum). Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Cool", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "the roots of Madder … be likewise of nature and temperature cold and dry", "gloss": "European madder root is cold and dry.", "locator": "Book II, Chap. 460 'Of Madder', The Temperature", "not_counted_why": "Different species (Rubia tinctorum). Shown, not counted.", "note": "Different species (Rubia tinctorum). Shown, not counted.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Shown for context. Different species (Rubia tinctorum). Shown, not counted.", "assigns_moisture": "Dry", "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Madder is Temperate in respect to heat or cold, but is manifestly dry in the end of the first, or beginning of the second Degree", "gloss": "European madder is temperate and dry.", "locator": "Chapter 'Of Madder Great', XI The Qualities (OCR line ~107533)", "not_counted_why": "Different species (Rubia tinctorum). Shown, not counted.", "note": "Different species (Rubia tinctorum). Shown, not counted.", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry. The bitter and astringent tastes dry the fluids and reduce Kapha.", "temperature": "Cool. Ayurveda assigns sheeta virya (cooling) and it is pitta-pacifying; Chinese medicine records it as cold (han). A minority Ayurvedic reading calls its virya ushna (heating) on account of the pungent (katu) vipaka, but its blood-cooling action places it firmly on the cool side."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry, explained from the bitter and astringent tastes"}, "temperature": {"status": "clear", "why": "a definite Cool; the record cites Ayurvedic sheeta virya and Chinese han"}}}$j$::jsonb);

