insert into _energetics_batch values ('H218', $j${"agreement_state": "disagree", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; old sources agree)", "temperature": "stays Cool (clear modern value; old sources disagree, shown on page)"}, "batch": 2, "checked_no_reading": ["Culpeper's herbal chapter 'Ladies' Mantle': 'Venus claims the herb', no degree"], "counted_readings": {"moisture": [{"reading": "Dry", "source": "Gerard (1633)"}, {"reading": "Dry", "source": "Culpeper (1653)"}, {"reading": "Dry", "source": "Salmon (1710)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Warm", "source": "Culpeper (1653)"}, {"reading": "Warm", "source": "Salmon (1710)"}]}, "disagreement_text": "On temperature, Gerard (1633), Culpeper (1653) and Salmon (1710) read it as warm. The app keeps cool, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "Aerial parts, the leaf and flowering herb (Alchemillae herba), gathered in June and July when in flower and the leaves are at their best, then dried; the fresh root is occasionally used for its stronger astringency.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Lady's Mantle is like in temperature to little Sanicle, yet is it more drying and more binding.", "gloss": "Like sanicle in temperature, but more drying. Gerard's sanicle chapter (Book II, Chap. 364) says sanicle 'is hot and dry, and that in the second degree'.", "locator": "Book II, Chap. 365 'Of Lady's Mantle, or great Sanicle', The Temperature; read with Chap. 364 'Of Sanicle', The Temperature", "not_counted_why": "", "note": "The temperature is given by cross-reference to sanicle, which Gerard calls hot and dry in the second degree.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "Alchymilla. Ladies-Mantle. Is hot and dry, some say in the second degree, some say in the third", "gloss": "Lady's mantle is hot and dry (degree disputed).", "locator": "Catalogue of simples, Herbs, 'Alchymilla' (Gutenberg #49513 line ~16201)", "not_counted_why": "", "note": "", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: differs from the app temperature (source warm, app cool); agrees with the app moisture (dry).", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "It is hot and dry in the second Degree; Absterſive, Aſtringent, Strengthning and Vulnerary.", "gloss": "Lady's mantle is hot and dry in the second degree.", "locator": "Chap. CCCCXXI (421) 'Of Ladies-Mantle, or Lions-Foot', VII The Qualities (OCR line ~97563)", "not_counted_why": "", "note": "", "short": "Salmon (1710)", "source": "William Salmon, Botanologia: The English Herbal (London, 1710)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://archive.org/download/gri_33125012917387/gri_33125012917387_djvu.txt", "year": "1710"}], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

