-- H230 Fig (batch 2, 5 sources, SOURCES DISAGREE)
insert into _energetics_batch values ('H230', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; old sources agree)", "temperature": "stays Neutral (clear modern value; old sources disagree, shown on page)"}, "batch": 2, "checked_no_reading": ["Salmon, Botanologia (1710): no fig chapter found in the OCR text", "Bhāvaprakāśa and Rājanighaṇṭu: no entry for Ficus carica (udumbara and kākodumbarikā are other Ficus species)", "Porter Smith 1871, FICUS CARICA: 'stomachic and corrective qualities', actions only", "King's 1898, 'Ficus': no temperature or moisture"], "counted_readings": {"moisture": [{"reading": "Moist", "source": "Gerard (1633)"}], "temperature": [{"reading": "Warm", "source": "Gerard (1633)"}, {"reading": "Neutral", "source": "Culpeper (1653)"}, {"reading": "Neutral", "source": "Bencao Gangmu (1596)"}]}, "disagreement_text": "On temperature, the old sources disagree: Gerard (1633) reads it as warm; Culpeper (1653) and Bencao Gangmu (1596) read it as neutral. The app keeps neutral, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": ["The stored part covers both fresh and dried fruit, so readings on either are counted."], "part_used": "Fruit (fresh and dried syconium); milky latex and leaf used topically", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral with a classical basis (the record cites Chinese 'sweet and neutral')), so it stays Neutral. Moisture: stored value clear (a definite Moist), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source warm, app neutral); agrees with the app moisture (moist).", "assigns_moisture": "Moist", "assigns_temperature": "Warm", "corpus": "galenic-european", "counted": true, "counted_moisture": true, "counted_temperature": true, "excerpt": "The green figs new gathered are somewhat warm and moist: the dry and ripe figs are hot almost in the third degree, and withal sharp and biting.", "gloss": "Fresh figs are somewhat warm and moist; dried ripe figs are hot, almost in the third degree.", "locator": "Book III, Chap. 133 'Of the Fig Tree', The Temperature", "not_counted_why": "", "note": "Warm for both forms; moist is stated for the fresh fig.", "short": "Gerard (1633)", "source": "John Gerard, The Herball or Generall Historie of Plantes, enlarged by Thomas Johnson (1633 text; read in the Ex-Classics transcription and checked against the 1636 printing scanned at archive.org)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.exclassics.com/herbal/herball.txt", "year": "1633"}, {"agreement": "Counted: agrees with the app temperature (neutral).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "galenic-european", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "Temperate in respect of heat. Raisins of the sun, Currants, Figs, Pine Nuts, Dates, Sebastens.", "gloss": "Figs are temperate in respect of heat.", "locator": "Catalogue of simples, Fruits, Culpeper's temperature table (Gutenberg #49513 line ~19049)", "not_counted_why": "", "note": "Galenic 'temperate' counts as Neutral.", "short": "Culpeper (1653)", "source": "Nicholas Culpeper, The Complete Herbal (text of 1653; London: Thomas Kelly, 1850 edition as digitised by Project Gutenberg #49513)", "tier": "first-hand", "tradition": "Galenic (European)", "url": "https://www.gutenberg.org/cache/epub/49513/pg49513.txt", "year": "1653"}, {"agreement": "Counted: agrees with the app temperature (neutral).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "實氣味甘平無毒主治開胃止洩痢", "gloss": "Fruit: sweet, neutral, not toxic.", "locator": "卷三十一 果之三, 無花果, 實", "not_counted_why": "", "note": "", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. A second-hand report: the text credits another writer.", "assigns_moisture": "Dry", "assigns_temperature": "Warm", "corpus": "unani", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "Ibn Massouïh. La figue verte est moins chaude et moins sèche que la figue séchée.", "gloss": "Ibn al-Baytar quotes Ibn Masawaih: the green fig is less hot and less dry than the dried fig.", "locator": "Vol. I, no. 439 'Tin, Figue', pp. 326-327", "not_counted_why": "A second-hand report: the text credits another writer.", "note": "", "short": "Ibn al-Baytar, tr. Leclerc (1877)", "source": "Ibn al-Baytar, Traité des simples, tr. Lucien Leclerc, Vol. I (Notices et extraits des manuscrits, t. 23, pt. 1)", "tier": "second-hand-report", "tradition": "Unani (Arabic)", "url": "https://archive.org/download/NoticesEtExtraitsDesMss23P1/Notices_et_extraits_des_mss_23_p1_djvu.txt", "year": "1877"}, {"agreement": "Shown for context. Second-hand, and an action list.", "assigns_moisture": null, "assigns_temperature": "Cool", "corpus": "ayurvedic", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "the Hindus are fond of the fruit, which they consider to be cooling and nutrient", "gloss": "Reports Hindu opinion; 'cooling' in a list of effects.", "locator": "Vol. III pp. 342-343, FICUS CARICA, History, Uses &c.", "not_counted_why": "Second-hand, and an action list.", "note": "Second-hand, and an action list.", "short": "Pharmacographia Indica III (1893)", "source": "Dymock, Warden & Hooper, Pharmacographia Indica, Vol. III", "tier": "second-hand-report", "tradition": "Ayurvedic (Indian)", "url": "https://archive.org/download/b21960343_0003/b21960343_0003_djvu.txt", "year": "1893"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Neutral"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist"}, "temperature": {"status": "clear", "why": "a definite Neutral with a classical basis (the record cites Chinese 'sweet and neutral')"}}}$j$::jsonb);

-- H236 Colic Root (True Unicorn) (batch 2, 0 sources, no qualifying source)
insert into _energetics_batch values ('H236', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (stored value unclear; no pre-1900 source found, so nothing to replace it)"}, "batch": 2, "checked_no_reading": ["Schöpf 1787 no. 109 ALETRIS farinosa: 'QVAL. amara' (bitter), no temperature", "Rafinesque, Medical Flora Vol. I (1828), Aletris farinosa: no temperature", "King's 1898, 'Aletris': no temperature or moisture"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_pre1900_source_found": true, "notes": [], "part_used": "Dried rhizome and its fibrous rootlets, collected after flowering. Only the properly dried root is used medicinally: the fresh root is acrid and, in quantity, narcotic, emetic, and cathartic.", "researched": "2026-09-15", "rule": "Temperature: stored value unclear (the stored field says it 'leans cooling' in the bitter-tonic archetype, an inference rather than a sourced value); no first-hand pre-1900 source found, so the stored value stays for now. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Dry. A cool, draining bitter that dries and disperses a waterlogged, boggy, flatulent digestion; it tightens and tones lax tissue rather than lubricating it, and over-long use can leave a thin, dry constitution more depleted.", "temperature": "Cool. A cool, gently stimulant, acrid-bitter digestive tonic that drains and rouses a sluggish, boggy, under-functioning digestion rather than heating it. In the bitter-tonic archetype it leans cooling and draining, sharpening appetite and secretion while settling flatulent, colicky discomfort."}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "unclear", "why": "the stored field says it 'leans cooling' in the bitter-tonic archetype, an inference rather than a sourced value"}}}$j$::jsonb);

