-- H245 Blue Flag (batch 2, 0 sources, no qualifying source)
insert into _energetics_batch values ('H245', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 2, "checked_no_reading": ["Schöpf 1787 no. 17 IRIS versicolor: 'Radix mucilaginosa, dulcescens, acris', taste only", "Rafinesque, Medical Flora Vol. II (1830) supplement, Iris: no temperature", "Cook 1869, 'Iris Versicolor': 'acrid and stimulating' when fresh, action words", "King's 1898, 'Iris': no temperature or moisture", "Culpeper's Flower-de-luce and Water-flag are European irises (different species), not counted"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_pre1900_source_found": true, "notes": [], "part_used": "Rhizome, dried. The fresh rhizome is intensely acrid, emetic, and cathartic and is not taken internally; the dried, aged rhizome is milder and is the form used medicinally. It is often sold as Blue Flag root, though botanically it is a rhizome.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool, adjudicated in the record from named sources), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool, adjudicated in the record from named sources"}}}$j$::jsonb);

-- H249 Cordyceps (Caterpillar Fungus, Dong Chong Xia Cao) (batch 2, 1 source, SOURCES DISAGREE)
insert into _energetics_batch values ('H249', $j${"agreement_state": "disagree", "app_value": {"moisture": "Moist", "temperature": "Warm"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Moist (clear modern value; no pre-1900 source found)", "temperature": "stays Warm (clear modern value; old sources disagree, shown on page)"}, "batch": 2, "checked_no_reading": ["Bencao Gangmu (1596): no entry", "Porter Smith 1871, CORDYCEPS SINENSIS: description and trade only, no thermal quality"], "counted_readings": {"moisture": [], "temperature": [{"reading": "Neutral", "source": "Bencao Congxin (1757)"}]}, "disagreement_text": "On temperature, Bencao Congxin (1757) reads it as neutral. The app keeps warm, the modern reading of what the herb does in the body; the old readings are shown here but do not change it.", "no_pre1900_source_found": false, "notes": [], "part_used": "The whole caterpillar-fungus complex: the dark, slender, club-shaped fruiting body (stroma) of the fungus together with the mummified body of the ghost-moth larva (Thitarodes, formerly Hepialus) it has parasitized and consumed, harvested and dried whole. In modern practice the far more common material is cultured mycelium, above all the fermented Cs-4 strain (Paecilomyces hepiali) grown on grain or in liquid culture, which Bensky notes carries comparable clinical efficacy with less toxicity and without pressure on the scarce wild resource.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Warm with a stated TCM basis), so it stays Warm. Moisture: stored value clear (a definite Moist with a stated TCM basis (moistens Lung yin)), so it stays Moist.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: differs from the app temperature (source neutral, app warm).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "冬虫夏草 … 補肺腎。甘平保肺。益腎止血。化痰已劳嗽。", "gloss": "Cordyceps: tonifies lung and kidney; sweet, NEUTRAL; protects the lung, benefits the kidney.", "locator": "草部, 冬虫夏草", "not_counted_why": "", "note": "Bencao Congxin is the first standard materia medica to list cordyceps.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sources_agree": false, "stored_before": {"moisture": "Moist", "temperature": "Warm"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Moist with a stated TCM basis (moistens Lung yin)"}, "temperature": {"status": "clear", "why": "a definite Warm with a stated TCM basis"}}}$j$::jsonb);

-- H252 Hydrangea (Seven Barks) (batch 2, 0 sources, no qualifying source)
insert into _energetics_batch values ('H252', $j${"agreement_state": "none", "app_value": {"moisture": "Dry", "temperature": "Cool"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Dry (clear modern value; no pre-1900 source found)", "temperature": "stays Cool (clear modern value; no pre-1900 source found)"}, "batch": 2, "checked_no_reading": ["King's 1898, 'Hydrangea': no temperature or moisture", "Rafinesque, Medical Flora Vol. II (1830) supplement, Hydrangea: no temperature"], "counted_readings": {"moisture": [], "temperature": []}, "disagreement_text": "", "no_pre1900_source_found": true, "notes": [], "part_used": "Root and rhizome, dried (dug in autumn). The English name Seven Barks comes from the several thin, variously colored layers of bark that peel from the woody root. The root bark is the most active portion; it is decocted or, in the Eclectic tradition, tinctured from the fresh root as specific hydrangea.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Cool), so it stays Cool. Moisture: stored value clear (a definite Dry), so it stays Dry.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [], "sources_agree": false, "stored_before": {"moisture": "Dry", "temperature": "Cool"}, "stored_value_status": {"moisture": {"status": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Cool"}}}$j$::jsonb);

