": "clear", "why": "a definite Dry"}, "temperature": {"status": "clear", "why": "a definite Warm with a stated modern basis (Holmes)"}}}$j$::jsonb);

-- H256 Mimosa (Silk Tree Bark) (batch 2, 3 sources, sources agree)
insert into _energetics_batch values ('H256', $j${"agreement_state": "agree", "app_value": {"moisture": "Neutral", "temperature": "Neutral"}, "app_value_changed": {"moisture": false, "temperature": false}, "app_value_lines": {"moisture": "stays Neutral (stored value unclear; no pre-1900 source found, so nothing to replace it)", "temperature": "stays Neutral (clear modern value; old sources agree)"}, "batch": 2, "checked_no_reading": [], "counted_readings": {"moisture": [], "temperature": [{"reading": "Neutral", "source": "Shennong Bencao Jing (c. 200 CE)"}]}, "disagreement_text": "", "no_pre1900_source_found": false, "notes": ["Bark is the stored primary part."], "part_used": "Bark (He Huan Pi, the dried stem and branch bark) primarily, and the flower (He Huan Hua, the fragrant pink flower). The bark is decocted for its shen-calming and blood-invigorating action; the sweeter flower is a gentler, more purely spirit-calming preparation.", "researched": "2026-09-15", "rule": "Temperature: stored value clear (a definite Neutral, which the record says its sources agree on), so it stays Neutral. Moisture: stored value unclear (the record says Neutral was set because the herb is neither drying nor moistening, with no source named); no first-hand pre-1900 source found, so the stored value stays for now.", "rule_general": "FINAL founder rules 2026-09-15: clear stored modern value stays; unclear or missing value set by majority of first-hand pre-1900 sources; tie broken by the oldest first-hand written source, Neutral if the oldest sources are themselves tied; copied readings count once; group statements, second-hand reports, other parts and other species shown but not counted; snigdha and 潤 = Moist, rūkṣa and 燥 = Dry.", "sources": [{"agreement": "Counted: agrees with the app temperature (neutral).", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": true, "counted_moisture": false, "counted_temperature": true, "excerpt": "合歡　味甘，平。主安五臟，利心志。令人獻樂無憂。", "gloss": "Albizia: sweet, neutral. Calms the five organs, gladdens the heart.", "locator": "中經, 合歡", "not_counted_why": "", "note": "", "short": "Shennong Bencao Jing (c. 200 CE)", "source": "神農本草經 (Shennong Bencao Jing, c. 200 CE), Sun Xingyan recension", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/神農本草經_(孫星衍)", "year": "c. 200 CE (recension 1799)"}, {"agreement": "Shown for context. Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "木皮…氣味甘平無毒主治安五臟和心志令人歡樂無憂", "gloss": "Bark: sweet, neutral, not toxic.", "locator": "卷三十五下 木之二, 合歡, 木皮", "not_counted_why": "Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "note": "Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "short": "Bencao Gangmu (1596)", "source": "李時珍, 本草綱目 (Li Shizhen, Bencao Gangmu), Siku Quanshu text", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草綱目_(四庫全書本)/", "year": "1596"}, {"agreement": "Shown for context. Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "assigns_moisture": null, "assigns_temperature": "Neutral", "corpus": "chinese", "counted": false, "counted_moisture": false, "counted_temperature": false, "excerpt": "合欢皮 … 甘平。安五臟。和心志。令人欢樂無忧。", "gloss": "Albizia bark: sweet, neutral.", "locator": "卷八 木部, 合欢皮", "not_counted_why": "Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "note": "Repeats the Shennong entry word for word, so it counts once, credited to Shennong.", "short": "Bencao Congxin (1757)", "source": "吳儀洛, 本草從新 (Wu Yiluo, Bencao Congxin)", "tier": "first-hand", "tradition": "Chinese", "url": "https://zh.wikisource.org/wiki/本草從新", "year": "1757"}], "sourc