r", "why": "a definite Warm"}}}$j$::jsonb);

do $do$
declare
  rec record;
  n int;
  written int := 0;
  skipped int := 0;
begin
  for rec in select herb_id, citation from _energetics_batch order by herb_id loop
    update public.herbs h
       set energetics_citation = rec.citation,
           last_updated = now()
     where h.herb_id = rec.herb_id
       and h.energetics_citation is distinct from rec.citation
       and (h.energetics_citation is null or h.energetics_citation ? 'batch');
    get diagnostics n = row_count;
    if n = 1 then
      written := written + 1;
    else
      if exists (select 1 from public.herbs
                  where herb_id = rec.herb_id and energetics_citation = rec.citation) then
        skipped := skipped + 1;
      else
        raise exception '%.energetics_citation: live value is neither NULL nor a batch object (or the herb is missing); not overwritten', rec.herb_id;
      end if;
    end if;
  end loop;
  raise notice 'energetics sources: % written, % already current', written, skipped;
end
$do$;

-- -----------------------------------------------------------------------------
-- 3. The read surface. Owner-privileged (public.herbs is RLS using(false), so a
--    security_invoker view would be empty), SELECT only for clients, and it
--    returns ONLY the 50 herbs carrying a batch object. A herb with no row here
--    renders nothing on the page: silence, never an invented claim.
-- -----------------------------------------------------------------------------
create or replace view public.herb_energetics_evidence_v as
select
  h.herb_id,
  (h.energetics_citation->>'batch')::int as batch,
  coalesce((h.energetics_citation->>'no_pre1900_source_found')::boolean, false)
    as no_pre1900_source_found,
  coalesce((h.energetics_citation->>'sources_agree')::boolean, false) as sources_agree,
  h.energetics_citation->>'agreement_state' as agreement_state,
  nullif(h.energetics_citation->>'disagreement_text', '') as disagreement_text,
  h.energetics_citation->>'rule' as rule,
  jsonb_array_length(coalesce(h.energetics_citation->'sources', '[]'::jsonb))
    as source_count,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'sources' else null::jsonb end as sources,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'checked_no_reading' else null::jsonb end
    as checked_no_reading,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->'counted_readings' else null::jsonb end
    as counted_readings,
  case when current_user_at_least('root'::text)
       then h.energetics_citation->>'rule_general' else null::text end as rule_general
  from public.herbs h
 where h.energetics_citation ? 'batch'
   and coalesce(h.status, '') not like 'Hidden%';

comment on view public.herb_energetics_evidence_v is 'Pre-1900 energetics evidence per herb (founder decision 2026-09-15). Free and anon read the agreement state, the disagreement sentence, the no-source flag and the basis line; the sources, the texts searched that gave no reading and the vote tally are Root and above.';

revoke all on public.herb_energetics_evidence_v from anon, authenticated;
grant select on public.herb_energetics_evidence_v to anon, authenticated;
grant all on public.herb_energetics_evidence_v to service_role;

-- -----------------------------------------------------------------------------
-- 4. Verification. Any failure aborts the whole transaction.
-- -----------------------------------------------------------------------------
do $do$
declare
  bad text[] := '{}';
  n int;
  t text;
  m text;
  moved text;
begin
  -- 4a. 50 herbs carry a batch object, and each one has a sources array or the
  --     honest no-source flag.
  select count(*) into n from public.herbs where energetics_citation ? 'batch';
  if n <> 50 then bad := bad || ('batch citations: ' || n || ', expected 50'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (jsonb_typeof(energetics_citation->'sources') = 'array'
          or (energetics_citation->>'no_pre1900_source_found')::boolean);
  if n <> 50 then bad := bad || ('batch citations with a sources array or the no-source flag: ' || n || ', expected 50'); end if;
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 1;
  if n <> 25 then bad := bad || ('batch 1 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs where (energetics_citation->>'batch')::int = 2;
  if n <> 25 then bad := bad || ('batch 2 herbs: ' || n || ', expected 25'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0
     and not (energetics_citation->>'no_pre1900_source_found')::boolean;
  if n <> 0 then bad := bad || (n || ' herb(s) have no source and no no-source flag'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch' and coalesce(energetics_citation->>'rule', '') = '';
  if n <> 0 then bad := bad || (n || ' herb(s) carry no basis line'); end if;

  -- Every stored source carries the fields the page renders, and every source
  -- that did NOT count says why it did not.
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch';
  if n <> 125 then bad := bad || ('stored sources: ' || n || ', expected 125'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s ? 'source' and s ? 'year' and s ? 'corpus' and s ? 'tier'
              and s ? 'assigns_temperature' and s ? 'assigns_moisture'
              and s ? 'excerpt' and s ? 'locator' and s ? 'url'
              and s ? 'agreement' and s ? 'counted');
  if n <> 0 then bad := bad || (n || ' source(s) are missing a required field'); end if;
  select count(*) into n
    from public.herbs h,
         lateral jsonb_array_elements(coalesce(h.energetics_citation->'sources', '[]'::jsonb)) s
   where h.energetics_citation ? 'batch'
     and not (s->>'counted')::boolean
     and coalesce(s->>'not_counted_why', '') = '';
  if n <> 0 then bad := bad || (n || ' uncounted source(s) do not say why they were not counted'); end if;

  -- 4b. The older 69 single-source citations are untouched.
  select count(*) into n from public.herbs
   where energetics_citation is not null and not (energetics_citation ? 'batch');
  if n <> 69 then bad := bad || ('pre-existing single-source citations: ' || n || ', expected 69'); end if;

  -- 4c. Never claim agreement the data does not carry: a herb marked as
  --     disagreeing must carry the founder's sentence, and one marked as
  --     agreeing must not carry a disagreement sentence.
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'agreement_state' = 'disagree'
     and coalesce(energetics_citation->>'disagreement_text', '') = '';
  if n <> 0 then bad := bad || (n || ' disagreeing herb(s) carry no disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and coalesce(energetics_citation->>'disagreement_text', '') <> '';
  if n <> 0 then bad := bad || (n || ' agreeing herb(s) also carry a disagreement sentence'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and (energetics_citation->>'sources_agree')::boolean
     and jsonb_array_length(coalesce(energetics_citation->'sources', '[]'::jsonb)) = 0;
  if n <> 0 then bad := bad || (n || ' herb(s) claim agreement with no sources at all'); end if;
  select count(*) into n from public.herbs
   where energetics_citation ? 'batch'
     and energetics_citation->>'disagreement_text' like '%' || chr(8212) || '%';
  if n <> 0 then bad := bad || (n || ' disagreement sentence(s) contain an em dash'); end if;

  -- 4d. The three approved values, and nothing else.
  select temperature into t from public.herbs where herb_id = 'H132';
  if t is distinct from 'Warm' then bad := bad || ('H132 temperature is ' || coalesce(t, 'NULL') || ', expected Warm'); end if;
  select moisture into t from public.herbs where herb_id = 'H120';
  if t is distinct from 'Dry' then bad := bad || ('H120 moisture is ' || coalesce(t, 'NULL') || ', expected Dry'); end if;
  select temperature into t from public.herbs where herb_id = 'H287';
  if t is distinct from 'Warm' then bad := bad || ('H287 temperature is ' || coalesce(t, 'NULL') || ', expected Warm'); end if;
  select count(*), string_agg(h.herb_id, ', ' order by h.herb_id) into n, moved
    from public.herbs h join _energetics_before b using (herb_id)
   where h.temperature is distinct from b.temperature
      or h.moisture is distinct from b.moisture;
  if n <> 3 or moved <> 'H120, H132, H287' then
    bad := bad || ('energetics moved on ' || n || ' herb(s): ' || coalesce(moved, 'none') || '; expected exactly H120, H132, H287');
  end if;
  select count(*) into n from public.herbs;
  if n <> (select count(*) from _energetics_before) then
    bad := bad || 'the herb count changed'::text;
  end if;

  -- 4e. The view: 50 rows, Root-only source list, no client writes.
  select count(*) into n from public.herb_energetics_evidence_v;
  if n <> 50 then bad := bad || ('herb_energetics_evidence_v rows: ' || n || ', expected 50'); end if;
  select pg_get_viewdef('public.herb_energetics_evidence_v'::regclass, true) into t;
  if t !~ 'current_user_at_least' then
    bad := bad || 'herb_energetics_evidence_v does not gate its source list'::text;
  end if;
  if not has_table_privilege('anon', 'public.herb_energetics_evidence_v', 'SELECT')
     or not has_table_privilege('authenticated', 'public.herb_energetics_evidence_v', 'SELECT') then
    bad := bad || 'herb_energetics_evidence_v is not client-readable'::text;
  end if;
  foreach m in array array['INSERT', 'UPDATE', 'DELETE', 'TRUNCATE'] loop
    if has_table_privilege('anon', 'public.herb_energetics_evidence_v', m)
       or has_table_privilege('authenticated', 'public.herb_energetics_evidence_v', m) then
      bad := bad || ('herb_energetics_evidence_v grants ' || m || ' to a client role');
    end if;
  end loop;
  if exists (select 1 from pg_class where oid = 'public.herb_energetics_evidence_v'::regclass
              and coalesce(reloptions, '{}') && array['security_invoker=true', 'security_invoker=on']) then
    bad := bad || 'herb_energetics_evidence_v is security_invoker (it would return nothing)'::text;
  end if;

  if array_length(bad, 1) is not null then
    raise exception 'energetics sources: checks failed: %', array_to_string(bad, '; ');
  end if;
end
$do$;

-- 4f. The gate, proved by READING the view as the anon role rather than by
--     reading its definition. A blind check that returns nothing looks healthy,
--     so this asserts a NON-EMPTY free result and a NULL source list together.
do $do$
declare
  bad text[] := '{}';
  free_text text;
  free_flag boolean;
  src jsonb;
  seen int;
begin
  begin
    set local role anon;
  exception when insufficient_privilege then
    raise notice 'cannot SET ROLE anon here; the functional tier check was skipped';
    return;
  end;
  select count(*) into seen from public.herb_energetics_evidence_v;
  if seen <> 50 then bad := bad || ('anon sees ' || seen || ' evidence rows, expected 50'); end if;
  select disagreement_text, sources into free_text, src
    from public.herb_energetics_evidence_v where herb_id = 'H111';
  if coalesce(free_text, '') = '' then
    bad := bad || 'anon cannot read the disagreement sentence on H111'::text;
  end if;
  if src is not null then
    bad := bad || 'anon can read the Root source list on H111'::text;
  end if;
  select no_pre1900_source_found into free_flag
    from public.herb_energetics_evidence_v where herb_id = 'H102';
  if free_flag is not true then
    bad := bad || 'anon cannot read the no-source flag on H102'::text;
  end if;
  reset role;
  if array_length(bad, 1) is not null then
    raise exception 'energetics sources: tier gate failed: %', array_to_string(bad, '; ');
  end if;
end
$do$;

commit;
